import {ensureLayerOrder} from './layers.js';
import {migrateMirrors,resolveMirrorChanges,materializeInstances} from './mirror-service.js';
import {migrateDocument} from './document.js';
import {refreshPanels,resolvePanelMirrors,migratePanelAnchors} from './panels.js';
import {bindTemplateGeometry} from './template-bindings.js';
import {templateEdges} from './template-metadata.js';
import {ensureEdges,semanticEdges} from './edges.js';
import {initializeStructure,syncStructure,syncAttachments} from './structure.js';
import {clone,uid} from './core.js';
export const categories={structure:'Estructura',construction:'Construcción',detail:'Detalles',graphic:'Gráficos'};
export function inferCategory(o){if(o.category)return o.category;if(['image','text'].includes(o.type)||o.role==='graphicArea')return 'graphic';if(o.source||(!o.closed&&o.type==='path'))return 'construction';if(o.role==='body'||/^(Manga|Puño|Cintura|Cuello|Capucha)/.test(o.name))return 'structure';return 'detail';}
export function migrateModel(p){const version=p.schemaVersion||1;p.schemaVersion=Math.max(10,version);migrateDocument(p);p.categoryState??={};p.applyTo??='both';p.garment??={links:[],dimensions:{},diverged:[]};p.variants??=[];p.activeVariant??='V1';for(const [view,os]of Object.entries(p.views)){for(const o of os){ensureEdges(o);o.category=inferCategory(o);o.semanticType??=o.component?.kind||o.role||o.type;if(version<4&&!o.semanticEdges&&o.category==='structure'){const meta=templateEdges[p.kind]?.[o.structureKey||o.name];if(meta&&o.nodes?.length===meta.count)semanticEdges(o,meta.edges);}}const groups=new Set(os.map(o=>o.group).filter(Boolean));p.groups??={front:[],back:[]};p.groups[view]??=[];for(const id of groups)if(!p.groups[view].some(g=>g.id===id))p.groups[view].push({id,name:'Grupo',category:os.find(o=>o.group===id)?.category||'detail'});}
if(!p.garment.initialized){p.garment.initialized=true;for(const a of p.views.front.filter(o=>o.category==='structure')){const b=p.views.back.find(o=>o.category==='structure'&&((a.structureKey&&o.structureKey===a.structureKey)||o.name===a.name));if(b){const key=a.structureKey||a.name;a.structureKey=b.structureKey=key;p.garment.links.push({key,front:a.id,back:b.id});}}}if(version<4)bindTemplateGeometry(p);initializeStructure(p);migrateMirrors(p);if(version<9)migratePanelAnchors(p);for(const view of Object.keys(p.views))ensureLayerOrder(p,view);return p;}
export function ancestors(p,view,o){const list=[];let id=o.group;const seen=new Set();while(id&&!seen.has(id)){seen.add(id);const g=p.groups?.[view]?.find(g=>g.id===id);if(!g)break;list.push(g);id=g.parent;}return list;}
function inheritedState(p,view,o,key){const seen=new Set();while(o){if(seen.has(o.id))return true;seen.add(o.id);if(o[key]||p.categoryState?.[o.category]?.[key]||ancestors(p,view,o).some(g=>g[key]))return true;const owner=o.panelOf||o.source||o.ownerId;o=owner?p.views[view].find(x=>x.id===owner):null;}return false;}
export function visible(p,view,o){return !inheritedState(p,view,o,'hidden');}
export function locked(p,view,o){return inheritedState(p,view,o,'locked');}
export function isolationIds(p,view,scope){if(!scope)return null;const os=p.views[view],ids=new Set();for(const o of os)if(o.id===scope||o.group===scope||ancestors(p,view,o).some(g=>g.id===scope))ids.add(o.id);let changed=true;while(changed){changed=false;for(const o of os){if(ids.has(o.id)&&o.source&&!ids.has(o.source)){ids.add(o.source);changed=true;}if(ids.has(o.source)&&!ids.has(o.id)){ids.add(o.id);changed=true;}}}return ids;}
export function reparent(p,view,id,target){const os=p.views[view],o=os.find(o=>o.id===id),gs=p.groups[view],g=gs.find(g=>g.id===id);if(!o&&!g)return false;const dest=gs.find(g=>g.id===target);if(g&&(target===id||groupAncestors(gs,target).includes(id)))return false;if(o){if(dest)o.group=dest.id;else delete o.group;}else if(dest)g.parent=dest.id;else delete g.parent;return true;}
function groupAncestors(gs,id){const out=[];while(id&&!out.includes(id)){out.push(id);id=gs.find(g=>g.id===id)?.parent;}return out;}
export {materializeInstances,detachInstances,createSymmetry} from './mirror-service.js';
export function reconcile(p,before,view,context={}){resolveMirrorChanges(p,before,view,context);migrateModel(p);const list=p.views[view],old=before?.views?.[view]||[];for(const o of list)ensureEdges(o,old.find(v=>v.id===o.id));syncAttachments(p,before,view);syncStructure(p,before,view);syncAttachments(p,before,view==='front'?'back':'front');resolvePanelMirrors(p,view);refreshPanels(list);resolveMirrorChanges(p,before,view,{...context,projectOnly:true});resolvePanelMirrors(p,view);materializeInstances(p,view);for(const side of Object.keys(p.views))ensureLayerOrder(p,side);}
export function variant(p,operation,name){const snapshot=()=>clone({views:p.views,groups:p.groups,garment:p.garment,categoryState:p.categoryState,layerOrder:p.layerOrder});p.variants??=[];if(operation==='switch'){let target=p.variants.find(v=>v.name===name);if(!target)return;const active=p.variants.find(v=>v.name===p.activeVariant);if(active)active.state=snapshot();else p.variants.push({id:uid(),name:p.activeVariant,state:snapshot()});Object.assign(p,clone(target.state));p.activeVariant=target.name;}if(operation==='duplicate'){const active=p.variants.find(v=>v.name===p.activeVariant);if(active)active.state=snapshot();else p.variants.push({id:uid(),name:p.activeVariant,state:snapshot()});p.activeVariant=name||'V'+(p.variants.length+1);p.variants.push({id:uid(),name:p.activeVariant,state:snapshot()});}if(operation==='rename'){const v=p.variants.find(v=>v.name===p.activeVariant);if(v)v.name=name;p.activeVariant=name;}if(operation==='delete'){const next=p.variants.find(v=>v.name!==p.activeVariant);if(!next)return;p.variants=p.variants.filter(v=>v.name!==p.activeVariant);Object.assign(p,clone(next.state));p.activeVariant=next.name;}}
